// QueueUpdated is the resolver for the queueUpdated field.
func (r *subscriptionResolver) QueueUpdated(ctx context.Context, queueID string) (<-chan *model.QueueUpdate, error) {
	if r.PubSub == nil {
		return nil, fmt.Errorf("pubsub is not configured")
	}

	st, err := r.requireStore()
	if err != nil {
		return nil, err
	}

	userID, err := requireAuthUserID(ctx)
	if err != nil {
		return nil, err
	}

	modeQueueID, err := parseUUID(queueID, "queue id")
	if err != nil {
		return nil, err
	}

	modeQueue, err := st.GetModeQueueByID(ctx, modeQueueID)
	if err != nil {
		return nil, err
	}
	gameMode, err := st.GetGameModeByID(ctx, modeQueue.ModeID)
	if err != nil {
		return nil, err
	}
	game, err := st.GetGameByID(ctx, gameMode.GameID)
	if err != nil {
		return nil, err
	}

	view, err := st.GetUserModeQueueView(ctx, modeQueueID, userID)
	if err != nil {
		return nil, err
	}

	initialLaunchURL := ""
	if view.Matched && view.SessionID != nil {
		initialLaunchURL, err = r.signLaunchURL(ctx, game, *view.SessionID, userID)
		if err != nil {
			initialLaunchURL = ""
		}
	}
	initial := queueUpdateFromView(view, initialLaunchURL)
	if initial != nil {
		if err := r.enrichQueueUpdateGaps(ctx, initial); err != nil {
			return nil, err
		}
	}

	messages, unsubscribe, err := r.PubSub.Subscribe(ctx, pubsub.UserQueueChannel(userID.String()))
	if err != nil {
		return nil, err
	}

	initialStatus := "none"
	if initial != nil {
		initialStatus = string(initial.Status)
	}
	pubsub.DebugLog(
		"subscription open user=%s queue=%s channel=%s initial=%s",
		userID,
		modeQueueID,
		pubsub.UserQueueChannel(userID.String()),
		initialStatus,
	)

	updates := make(chan *model.QueueUpdate, 2)
	go func() {
		defer close(updates)
		defer unsubscribe()

		if initial != nil {
			select {
			case updates <- initial:
				pubsub.DebugLog(
					"subscription initial user=%s queue=%s status=%s hasJoinUrl=%t",
					userID,
					modeQueueID,
					initial.Status,
					initial.JoinURL != nil && *initial.JoinURL != "",
				)
			case <-ctx.Done():
				pubsub.DebugLog("subscription cancelled before initial user=%s queue=%s", userID, modeQueueID)
				return
			}
		}

		for {
			select {
			case <-ctx.Done():
				pubsub.DebugLog("subscription closed user=%s queue=%s", userID, modeQueueID)
				return
			case payload, ok := <-messages:
				if !ok {
					pubsub.DebugLog("subscription broker closed user=%s queue=%s", userID, modeQueueID)
					return
				}
				event, err := pubsub.UnmarshalQueueEvent(payload)
				if err != nil {
					pubsub.DebugLog("subscription drop unmarshal user=%s queue=%s err=%v", userID, modeQueueID, err)
					continue
				}
				if event.QueueID != modeQueueID.String() {
					pubsub.DebugLog(
						"subscription drop queue mismatch user=%s want=%s got=%s status=%s",
						userID,
						modeQueueID,
						event.QueueID,
						event.Status,
					)
					continue
				}
				update := toGraphQLQueueUpdate(event)
				if err := r.enrichQueueUpdateGaps(ctx, update); err != nil {
					pubsub.DebugLog("subscription drop enrich user=%s queue=%s err=%v", userID, modeQueueID, err)
					continue
				}
				select {
				case updates <- update:
					pubsub.DebugLog(
						"subscription deliver user=%s queue=%s status=%s hasJoinUrl=%t",
						userID,
						modeQueueID,
						update.Status,
						update.JoinURL != nil && *update.JoinURL != "",
					)
				case <-ctx.Done():
					return
				}
			}
		}
	}()

	return updates, nil
}

